162	// parseReconSeq 解析操作序号：非负有符号 64 位整数。
163	func parseReconSeq(text, name string) (int64, error) {
164		v, err := strconv.ParseInt(strings.TrimSpace(text), 10, 64)
165		if err != nil {
166			return 0, fmt.Errorf("%s %q 不是非负整数: %w", name, text, err)
167		}
168		if v < 0 {
169			return 0, fmt.Errorf("%s不能为负数，收到 %d", name, v)
170		}
171		return v, nil
172	}
173	
174	// ledgerBalanceAt 返回账单在指定操作序号完成后的应付与实收：序号 0 以原
175	// 总金额为应付、零实收起算，与 bill ledger 相同截止的余额一致。
176	func ledgerBalanceAt(b *bill, events []ledgerEvent, seq int64) (payable, received int64) {
177		payable, received = b.TotalFee, 0
178		for _, ev := range events {
179			if ev.seq > seq {
180				break
181			}
182			payable, received = ev.afterPayable, ev.afterReceived
183		}
184		return payable, received
185	}
186	
187	// reconcileEvents 把区间内（起点之后、终点以内）涉及范围内账期的调整、
188	// 调整撤销、收款、分配更正、收款撤销与退款合并为按全局操作序号升序的列表。
189	// 调整仅纳入所属账期在范围内的操作；收款按登记时分配、撤销按撤销时最新
190	// 分配、更正按前后分配、退款按各月退款额判断是否涉及范围；终点之后的操作
191	// 不提前影响结果。
192	func reconcileEvents(s *state, customerID, startMonth, endMonth string, startSeq, endSeq int64) ([]reconEvent, error) {
193		inRange := func(m string) bool { return m >= startMonth && m <= endMonth }
194		inInterval := func(seq int64) bool { return seq > startSeq && seq <= endSeq }
195	
196		var ops []reconEvent
197		for _, a := range s.Adjustments {
198			if a.CustomerID != customerID || !inRange(a.Month) {
199				continue
200			}
201			if inInterval(a.Seq) {
202				ops = append(ops, reconEvent{
203					seq: a.Seq, kind: "调整", refID: a.ID, note: a.Reason,
204					changes: []reconMonthChange{{month: a.Month, deltaPayable: a.Amount}},
205				})
206			}
207			if a.Revoked && inInterval(a.RevokeSeq) {
208				neg, err := neg64(a.Amount)
209				if err != nil {
210					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出报表", a.ID, a.Amount)
211				}
212				ops = append(ops, reconEvent{
213					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID, note: a.RevokeReason, linkSeq: a.Seq,
214					changes: []reconMonthChange{{month: a.Month, deltaPayable: neg}},
215				})
216			}
217		}
218		for _, p := range s.Payments {
219			if p.CustomerID != customerID {
220				continue
221			}
222			if inInterval(p.Seq) {
223				// 多月汇款只按范围内分配计入实收，不按汇款总额重复累加。
224				var changes []reconMonthChange
225				for _, al := range p.Allocations {
226					if inRange(al.Month) {
227						changes = append(changes, reconMonthChange{month: al.Month, deltaReceived: al.Amount, alloc: al.Amount})
228					}
229				}
230				if len(changes) > 0 {
231					ops = append(ops, reconEvent{
232						seq: p.Seq, kind: "收款", refID: p.ID, note: p.Note, payTotal: p.Total, changes: changes,
233					})
234				}
235			}
236			// 以登记分配为起点按序号回放更正：每次更正按前后分配判断是否涉及
237			// 范围——范围内转移即使汇总变化为 0 也保留，跨范围转入或转出按
238			// 实际差额计入。
239			running := p.Allocations
240			for _, c := range correctionsFor(s, p.ID) {
241				before := running
242				running = c.Allocations
243				if !inInterval(c.Seq) {
244					continue
245				}
246				var changes []reconMonthChange
247				for _, m := range unionMonths(before, c.Allocations) {
248					if !inRange(m) {
249						continue
250					}
251					b4, af := allocAmountFor(before, m), allocAmountFor(c.Allocations, m)
252					if b4 == 0 && af == 0 {
253						continue
254					}
255					changes = append(changes, reconMonthChange{
256						month: m, deltaReceived: af - b4, beforeAlloc: b4, afterAlloc: af,
257					})
258				}
259				if len(changes) > 0 {
260					ops = append(ops, reconEvent{
261						seq: c.Seq, kind: "更正", refID: c.ID, note: c.Reason, payID: p.ID, changes: changes,
262					})
263				}
264			}
265			// 撤销取消的是撤销发生时的最新分配（更正序号均先于撤销序号，
266			// 终点之后的操作不会提前影响结果）。
267			if p.Revoked && inInterval(p.RevokeSeq) {
268				var changes []reconMonthChange
269				for _, al := range running {
270					if inRange(al.Month) {
271						changes = append(changes, reconMonthChange{month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount})
272					}
273				}
274				if len(changes) > 0 {
275					ops = append(ops, reconEvent{
276						seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID, note: p.RevokeReason,
277						linkSeq: p.Seq, payTotal: p.Total, changes: changes,
278					})
279				}
280			}
281			// 跨月退款作为一次操作：只按范围内各月退款额减少实收，不按整笔
282			// 总额重复累减；退款不可撤销，记录永久保留。
283			for _, r := range refundsFor(s, p.ID) {
284				if !inInterval(r.Seq) {
285					continue
286				}
287				var changes []reconMonthChange
288				for _, al := range r.Allocations {
289					if inRange(al.Month) {
290						changes = append(changes, reconMonthChange{month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount})
291					}
292				}
293				if len(changes) > 0 {
294					ops = append(ops, reconEvent{
295						seq: r.Seq, kind: "退款", refID: r.ID, note: r.Reason, payID: p.ID, changes: changes,
296					})
297				}
298			}
299		}
300		// 全局操作序号唯一，按序号排序即得到确定性的展示顺序。
301		sort.Slice(ops, func(i, j int) bool { return ops[i].seq < ops[j].seq })
302		return ops, nil
303	}
