305	func printReconcile(cust *customer, startMonth, endMonth string, startSeq, endSeq int64, seqDesc string, nextSeq int64,
306		bills []reconBill, sumOrig, startPaySum, startRecvSum, endPaySum, endRecvSum int128, ops []reconEvent) {
307	
308		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
309		fmt.Fprintf(stdout, "账期范围：%s 至 %s（UTC 自然月，包含首尾）\n", startMonth, endMonth)
310		fmt.Fprintf(stdout, "操作序号区间：起点 %d、终点 %d（%s）\n", startSeq, endSeq, seqDesc)
311		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
312		fmt.Fprintf(stdout, "范围内账单：%d 张（当前已存在账单，不补结算；各账单在序号 0 以原总金额为应付、零实收起算）\n", len(bills))
313	
314		if len(bills) == 0 {
315			fmt.Fprintln(stdout, "逐月余额：无（该客户在账期范围内当前没有已存在账单）")
316		} else {
317			fmt.Fprintf(stdout, "逐月余额（起点为序号 %d 完成后，终点为序号 %d 完成后）：\n", startSeq, endSeq)
318			for i, rb := range bills {
319				fmt.Fprintf(stdout, "  %d. 月份 %s：账单 %s，原总金额 %d 分（%s）\n",
320					i+1, rb.b.Month, rb.b.ID, rb.b.TotalFee, moneyFen(rb.b.TotalFee))
321				fmt.Fprintf(stdout, "     起点：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
322					rb.startPay, moneyFen(rb.startPay), rb.startRecv, moneyFen(rb.startRecv),
323					rb.startPay-rb.startRecv, moneyFen(rb.startPay-rb.startRecv))
324				fmt.Fprintf(stdout, "     终点：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
325					rb.endPay, moneyFen(rb.endPay), rb.endRecv, moneyFen(rb.endRecv),
326					rb.endPay-rb.endRecv, moneyFen(rb.endPay-rb.endRecv))
327			}
328		}
329		fmt.Fprintf(stdout, "各列汇总（%d 张账单）：\n", len(bills))
330		fmt.Fprintf(stdout, "  原总金额合计：%s 分（%s）\n", sumOrig, moneyFen128(sumOrig))
331		fmt.Fprintf(stdout, "  起点合计：应付 %s 分（%s），实收 %s 分（%s），未收余额 %s 分（%s）\n",
332			startPaySum, moneyFen128(startPaySum), startRecvSum, moneyFen128(startRecvSum),
333			startPaySum.sub(startRecvSum), moneyFen128(startPaySum.sub(startRecvSum)))
334		fmt.Fprintf(stdout, "  终点合计：应付 %s 分（%s），实收 %s 分（%s），未收余额 %s 分（%s）\n",
335			endPaySum, moneyFen128(endPaySum), endRecvSum, moneyFen128(endRecvSum),
336			endPaySum.sub(endRecvSum), moneyFen128(endPaySum.sub(endRecvSum)))
337	
338		if len(ops) == 0 {
339			fmt.Fprintf(stdout, "区间内账后操作：无（序号 %d 之后、%d 以内无涉及范围内账单的操作）\n", startSeq, endSeq)
340		} else {
341			fmt.Fprintf(stdout, "区间内账后操作（序号 %d 之后、%d 以内，按全局操作序号升序）：\n", startSeq, endSeq)
342			for i, ev := range ops {
343				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatReconEvent(ev))
344			}
345		}
346		fmt.Fprintln(stdout, "说明：逐月两端余额与相同截止序号的 bill ledger 一致；终点为存档最新序号时与 bill show 一致。")
347	}
