349	// formatReconEvent 渲染一条合并后的账后操作：序号、类型、记录标识、原因
350	// 或备注、撤销或更正关联、范围内各月的应付及实收变化，以及事件后的范围
351	// 内汇总余额；收款类事件同时说明汇款总额（总额不计入范围内实收）。
352	func formatReconEvent(ev reconEvent) string {
353		parts := make([]string, len(ev.changes))
354		for i, ch := range ev.changes {
355			switch ev.kind {
356			case "调整", "撤销调整":
357				parts[i] = fmt.Sprintf("%s 应付 %+d 分", ch.month, ch.deltaPayable)
358			case "收款":
359				parts[i] = fmt.Sprintf("%s 实收 %+d 分（分配 %d 分）", ch.month, ch.deltaReceived, ch.alloc)
360			case "更正":
361				parts[i] = fmt.Sprintf("%s 实收 %+d 分（分配 %d 分 → %d 分）", ch.month, ch.deltaReceived, ch.beforeAlloc, ch.afterAlloc)
362			case "退款":
363				parts[i] = fmt.Sprintf("%s 实收 %+d 分（退款 %d 分）", ch.month, ch.deltaReceived, ch.alloc)
364			default: // 撤销收款
365				parts[i] = fmt.Sprintf("%s 实收 %+d 分（取消分配 %d 分）", ch.month, ch.deltaReceived, ch.alloc)
366			}
367		}
368		changes := strings.Join(parts, "，")
369		after := fmt.Sprintf("事后汇总：应付 %s 分，实收 %s 分，未收余额 %s 分",
370			ev.afterPay, ev.afterRecv, ev.afterPay.sub(ev.afterRecv))
371		switch ev.kind {
372		case "调整":
373			return fmt.Sprintf("序号 %d 调整 %s：原因：%s；范围内变化：%s → %s",
374				ev.seq, ev.refID, ev.note, changes, after)
375		case "撤销调整":
376			return fmt.Sprintf("序号 %d 撤销调整 %s（关联序号 %d 的调整 %s）：原因：%s；范围内变化：%s → %s",
377				ev.seq, ev.refID, ev.linkSeq, ev.refID, ev.note, changes, after)
378		case "收款":
379			return fmt.Sprintf("序号 %d 收款 %s：备注：%s；汇款总额 %d 分（%s）；范围内变化：%s → %s",
380				ev.seq, ev.refID, ev.note, ev.payTotal, moneyFen(ev.payTotal), changes, after)
381		case "更正":
382			return fmt.Sprintf("序号 %d 更正 %s（关联收款 %s）：原因：%s；范围内变化：%s → %s",
383				ev.seq, ev.refID, ev.payID, ev.note, changes, after)
384		case "退款":
385			return fmt.Sprintf("序号 %d 退款 %s（关联收款 %s）：原因：%s；范围内变化：%s → %s",
386				ev.seq, ev.refID, ev.payID, ev.note, changes, after)
387		default: // 撤销收款
388			return fmt.Sprintf("序号 %d 撤销收款 %s（关联序号 %d 的收款 %s）：原因：%s；汇款总额 %d 分（%s）；范围内变化：%s → %s",
389				ev.seq, ev.refID, ev.linkSeq, ev.refID, ev.note, ev.payTotal, moneyFen(ev.payTotal), changes, after)
390		}
391	}
392

