	// 序号非法：负数、非整数、起点晚于终点、超过存档上限。
	h.runExpectErr("bill", "reconcile", "c1", "2026-01", "2026-03", "-1", "3")
	h.runExpectErr("bill", "reconcile", "c1", "2026-01", "2026-03", "0", "x")
	h.runExpectErr("bill", "reconcile", "c1", "2026-01", "2026-03", "4", "3")
