	h.runExpectErr("bill", "correct", "r1", "c1", "理由", "2026-09")
	h.runExpectErr("bill", "correct", "r1", "c1", "理由", "2026-9:700")
	h.runExpectErr("bill", "correct", "r1", "c1", "理由", "2026-13:700")
