	h.runExpectErr("bill", "correct", "r1", "c1", "理由", "2026-09:abc")
	h.runExpectErr("bill", "correct", "r1", "c1", "理由", "2026-09:400", "2026-09:300")
	// 合计不等于原总额（700）。
