// 保存失败整批不生效：原有账单、用量与其他状态不变，排除故障后原清单可重试。
func TestSettleBatchSaveFailureRollsBack(t *testing.T) {
	h := newHarness(t)
	h.mustRun("customer", "add", "c1", "甲方", "100")
	h.mustRun("customer", "add", "c2", "乙方", "100")
	f := h.writeFile("u.csv", csvHeader+
