3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// 账后操作共享计算（仅供 bill ledger 单账单流水与 bill reconcile 跨账期报表
9	// 使用；结算、账单展示、载入校验与账后登记的持久化行为不经过这里）。
10	//
11	// 调整、调整撤销、收款、分配更正、收款撤销与退款的“业务归属（影响哪些账单
12	// 月份）与金额影响”只在本文件推导一次：先把存档记录展开为客户维度、按全局
13	// 操作序号升序的中立事件流，再由两类查询分别做范围筛选与展示。
14	//
15	// 共同的业务口径：
16	//   - 流水按全局序号升序，以原总金额为初始应付、零实收起算；
17	//   - 更正按发生时的前后分配逐月计算（后值减前值），撤销取消撤销当时的最新
18	//     分配，退款只减少对应月份实收；
19	//   - 撤销在其发生序号抵消原操作，已撤销记录在撤销之前仍计入；
20	//   - 截止后的操作由查询方自行筛选，不能提前影响历史余额；
21	//   - 同名的调整、收款、更正、退款按类型关联，互不混淆。
22	
23	const (
24		postOpAdjust       = "调整"
25		postOpRevokeAdjust = "撤销调整"
26		postOpPayment      = "收款"
27		postOpCorrect      = "更正"
28		postOpRevokePay    = "撤销收款"
29		postOpRefund       = "退款"
30	)
31	
32	// postMonthDelta 是一次账后操作对单个月份的金额影响。deltaPayable/
33	// deltaReceived 为带符号的实际影响（撤销与退款已取负）；alloc 为展示用的
34	// 业务金额（收款登记分配、撤销取消的最新分配、退款该月额），beforeAlloc/
35	// afterAlloc 仅更正事件使用。中立流中同一月份不会前后分配均为零。
36	type postMonthDelta struct {
37		month         string
38		deltaPayable  int64
39		deltaReceived int64
40		alloc         int64
41		beforeAlloc   int64
42		afterAlloc    int64
43	}
44	
45	// postOp 是一次账后操作的中立表示。调整类事件填 adjustID；收款相关事件填
46	// paymentID，更正与退款另填 correctionID/refundID。linkSeq 仅撤销类事件
47	// 非零（关联原操作序号）；payTotal 为收款类事件的汇款总额。
48	type postOp struct {
49		seq          int64
50		kind         string
51		adjustID     string
52		paymentID    string
53		correctionID string
54		refundID     string
55		note         string
56		linkSeq      int64
57		payTotal     int64
58		deltas       []postMonthDelta // 涉及月份，按月份升序
59	}
60	
61	// refID 返回事件的原记录标识；同名标识在不同类型事件中各自独立。
62	func (op postOp) refID() string {
63		switch op.kind {
64		case postOpAdjust, postOpRevokeAdjust:
65			return op.adjustID
66		case postOpPayment, postOpRevokePay:
67			return op.paymentID
68		case postOpCorrect:
69			return op.correctionID
70		default: // 退款
71			return op.refundID
72		}
73	}
74	
75	// postOpsForCustomer 把某客户的全部账后记录展开为按全局操作序号升序的中立
76	// 事件流，并做与具体查询无关的完整性核验：序号重复、撤销不晚于原操作、调整
77	// 金额无法取负都视为数据异常。载入校验已覆盖大部分约束，这里是两类查询共用
78	// 的最后防线。
79	func postOpsForCustomer(s *state, customerID string) ([]postOp, error) {
80		var ops []postOp
81		seen := make(map[int64]string) // 全局操作序号 -> 来源描述
82		add := func(op postOp) error {
83			desc := op.kind + " " + op.refID()
84			if prev, dup := seen[op.seq]; dup {
85				return fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出", op.seq, prev, desc)
86			}
87			seen[op.seq] = desc
88			if op.linkSeq != 0 && op.linkSeq >= op.seq {
89				return fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出", desc, op.seq, op.linkSeq)
90			}
91			ops = append(ops, op)
92			return nil
93		}
94	
95		// 调整与其撤销：每个事件只影响所属账期的应付。
96		for _, a := range s.Adjustments {
97			if a.CustomerID != customerID {
98				continue
99			}
100			if err := add(postOp{
101				seq: a.Seq, kind: postOpAdjust, adjustID: a.ID, note: a.Reason,
102				deltas: []postMonthDelta{{month: a.Month, deltaPayable: a.Amount}},
103			}); err != nil {
104				return nil, err
105			}
106			if a.Revoked {
107				neg, err := neg64(a.Amount)
108				if err != nil {
109					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出", a.ID, a.Amount)
110				}
111				if err := add(postOp{
112					seq: a.RevokeSeq, kind: postOpRevokeAdjust, adjustID: a.ID,
113					note: a.RevokeReason, linkSeq: a.Seq,
114					deltas: []postMonthDelta{{month: a.Month, deltaPayable: neg}},
115				}); err != nil {
116					return nil, err
117				}
118			}
119		}
120	
121		for _, p := range s.Payments {
122			if p.CustomerID != customerID {
123				continue
124			}
125			// 收款登记：多月汇款在中立流中保留全部月份分配，范围筛选交给查询方。
126			if err := add(postOp{
127				seq: p.Seq, kind: postOpPayment, paymentID: p.ID, note: p.Note,
128				payTotal: p.Total, deltas: paymentDeltas(p.Allocations),
129			}); err != nil {
130				return nil, err
131			}
132			// 以登记分配为起点按序号回放更正：每次更正按当时的前后分配逐月给出
133			// 差额；running 始终是该更正发生时生效（最新）的分配。
134			running := p.Allocations
135			for _, c := range correctionsFor(s, p.ID) {
136				var ds []postMonthDelta
137				for _, m := range unionMonths(running, c.Allocations) {
138					before := allocAmountFor(running, m)
139					after := allocAmountFor(c.Allocations, m)
140					if before == 0 && after == 0 {
141						continue // 前后均不涉及该月：不列更正
142					}
143					ds = append(ds, postMonthDelta{
144						month: m, deltaReceived: after - before,
145						beforeAlloc: before, afterAlloc: after,
146					})
147				}
148				if err := add(postOp{
149					seq: c.Seq, kind: postOpCorrect, paymentID: p.ID,
150					correctionID: c.ID, note: c.Reason, deltas: ds,
151				}); err != nil {
152					return nil, err
153				}
154				running = c.Allocations
155			}
156			// 整笔撤销取消撤销发生时的最新分配（running 即此时最新分配）。
157			if p.Revoked {
158				if err := add(postOp{
159					seq: p.RevokeSeq, kind: postOpRevokePay, paymentID: p.ID,
160					note: p.RevokeReason, linkSeq: p.Seq, payTotal: p.Total,
161					deltas: revokeDeltas(running),
162				}); err != nil {
163					return nil, err
164				}
165			}
166			// 退款在其发生序号只减少对应月份的实收，不可撤销；跨月退款是一次
167			// 操作、携带逐月变化，不按整笔总额重复累减。
168			for _, r := range refundsFor(s, p.ID) {
169				if err := add(postOp{
170					seq: r.Seq, kind: postOpRefund, paymentID: p.ID,
171					refundID: r.ID, note: r.Reason, deltas: refundDeltas(r.Allocations),
172				}); err != nil {
173					return nil, err
174				}
175			}
176		}
177	
178		sort.Slice(ops, func(i, j int) bool { return ops[i].seq < ops[j].seq })
179		return ops, nil
180	}
