182	// paymentDeltas 把收款登记分配转为逐月实收影响（分配即实收增加额）。
183	func paymentDeltas(allocs []paymentAllocation) []postMonthDelta {
184		ds := make([]postMonthDelta, 0, len(allocs))
185		for _, al := range allocs {
186			ds = append(ds, postMonthDelta{month: al.Month, deltaReceived: al.Amount, alloc: al.Amount})
187		}
188		sort.Slice(ds, func(i, j int) bool { return ds[i].month < ds[j].month })
189		return ds
190	}
191	
192	// revokeDeltas 把撤销当时的最新分配转为逐月实收影响（取消即实收减少）。
193	func revokeDeltas(allocs []paymentAllocation) []postMonthDelta {
194		ds := make([]postMonthDelta, 0, len(allocs))
195		for _, al := range allocs {
196			ds = append(ds, postMonthDelta{month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount})
197		}
198		sort.Slice(ds, func(i, j int) bool { return ds[i].month < ds[j].month })
199		return ds
200	}
201	
202	// refundDeltas 把一笔退款的各月退款额转为逐月实收影响。
203	func refundDeltas(allocs []paymentAllocation) []postMonthDelta {
204		ds := make([]postMonthDelta, 0, len(allocs))
205		for _, al := range allocs {
206			ds = append(ds, postMonthDelta{month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount})
207		}
208		sort.Slice(ds, func(i, j int) bool { return ds[i].month < ds[j].month })
209		return ds
210	}
211	
212	// deltaForMonth 返回事件在指定月份的逐月影响；该月不在事件涉及月份中时为 nil。
213	func (op postOp) deltaForMonth(month string) *postMonthDelta {
214		for i := range op.deltas {
215			if op.deltas[i].month == month {
216				return &op.deltas[i]
217			}
218		}
219		return nil
220	}
221	
222	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
223	// 分配更正、撤销收款或退款。它是共享中立事件流的单账单投影；事件按全局操作
224	// 序号升序回放，afterPayable/afterReceived 在逐步核验时填充。
225	type ledgerEvent struct {
226		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
227		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款 / 退款
228		refID         string // 原记录标识（调整标识、收款标识、更正标识或退款标识）
229		deltaPayable  int64  // 对当前应付的影响（分，带符号）
230		deltaReceived int64  // 对实收的影响（分，带符号）
231		note          string // 原因（调整/更正/退款/撤销类）或备注（收款类）
232		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
233		payTotal      int64  // 收款类事件：汇款总额
234		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
235		payID         string // 更正/退款事件：关联收款标识
236		beforeAlloc   int64  // 更正事件：本账单更正前分配
237		afterAlloc    int64  // 更正事件：本账单更正后分配
238		afterPayable  int64  // 事件后的应付（回放时填充）
239		afterReceived int64  // 事件后的实收（回放时填充）
240	}
